17	/// Provide suggested GitHub issue templates to user when Flutter encounters an error.
18	class GitHubTemplateCreator {
19	  GitHubTemplateCreator() :
20	      _client = (context.get<HttpClientFactory>() == null)
21	        ? HttpClient()
22	        : context.get<HttpClientFactory>()();
23	
24	  final HttpClient _client;
25	
26	  Future<String> toolCrashSimilarIssuesGitHubURL(String errorString) async {
27	    final String fullURL = 'https://github.com/flutter/flutter/issues?q=is%3Aissue+${Uri.encodeQueryComponent(errorString)}';
28	    return await _shortURL(fullURL);
29	  }
30	
31	  /// GitHub URL to present to the user containing encoded suggested template.
32	  ///
33	  /// Shorten the URL, if possible.
34	  Future<String> toolCrashIssueTemplateGitHubURL(
35	      String command,
36	      String errorString,
37	      String exception,
38	      StackTrace stackTrace,
39	      String doctorText
40	    ) async {
41	    final String title = '[tool_crash] $errorString';
42	    final String body = '''## Command
43	  ```
44	  $command
45	  ```
46	
47	  ## Steps to Reproduce
48	  1. ...
49	  2. ...
50	  3. ...
51	
52	  ## Logs
53	  $exception
54	  ```
55	  ${LineSplitter.split(stackTrace.toString()).take(20).join('\n')}
56	  ```
57	  ```
58	  $doctorText
59	  ```
60	
61	  ## Flutter Application Metadata
62	  ${_projectMetadataInformation()}
63	  ''';
64	
65	    final String fullURL = 'https://github.com/flutter/flutter/issues/new?'
66	      'title=${Uri.encodeQueryComponent(title)}'
67	      '&body=${Uri.encodeQueryComponent(body)}'
68	      '&labels=${Uri.encodeQueryComponent('tool,severe: crash')}';
69	
70	    return await _shortURL(fullURL);
71	  }
72	
73	  /// Provide information about the Flutter project in the working directory, if present.
74	  String _projectMetadataInformation() {
75	    FlutterProject project;
76	    try {
77	      project = FlutterProject.current();
78	    } on Exception catch (exception) {
79	      // pubspec may be malformed.
80	      return exception.toString();
81	    }
82	    try {
83	      final FlutterManifest manifest = project?.manifest;
84	      if (project == null || manifest == null || manifest.isEmpty) {
85	        return 'No pubspec in working directory.';
86	      }
87	      String description = '';
88	      description += '''
89	**Version**: ${manifest.appVersion}
90	**Material**: ${manifest.usesMaterialDesign}
91	**Android X**: ${manifest.usesAndroidX}
92	**Module**: ${manifest.isModule}
93	**Plugin**: ${manifest.isPlugin}
94	**Android package**: ${manifest.androidPackage}
95	**iOS bundle identifier**: ${manifest.iosBundleIdentifier}
96	''';
97	      final File file = project.flutterPluginsFile;
98	      if (file.existsSync()) {
99	        description += '### Plugins\n';
100	        for (String plugin in project.flutterPluginsFile.readAsLinesSync()) {
101	          final List<String> pluginParts = plugin.split('=');
102	          if (pluginParts.length != 2) {
103	            continue;
104	          }
105	          description += pluginParts.first;
106	        }
107	      }
108	
109	      return description;
110	    } on Exception catch (exception) {
111	      return exception.toString();
112	    }
113	  }
114	
115	  /// Shorten GitHub URL with git.io API.
116	  ///
117	  /// See https://github.blog/2011-11-10-git-io-github-url-shortener.
118	  Future<String> _shortURL(String fullURL) async {
119	    String url;
120	    try {
121	      printTrace('Attempting git.io shortener: $fullURL');
122	      final List<int> bodyBytes = utf8.encode('url=${Uri.encodeQueryComponent(fullURL)}');
123	      final HttpClientRequest request = await _client.postUrl(Uri.parse('https://git.io'));
124	      request.headers.set(HttpHeaders.contentLengthHeader, bodyBytes.length.toString());
125	      request.add(bodyBytes);
126	      final HttpClientResponse response = await request.close();
127	
128	      if (response.statusCode == 201) {
129	        url = response.headers[HttpHeaders.locationHeader]?.first;
130	      } else {
131	        printTrace('Failed to shorten GitHub template URL. Server responded with HTTP status code ${response.statusCode}');
132	      }
133	    } catch (sendError) {
134	      printTrace('Failed to shorten GitHub template URL: $sendError');
135	    }
136	
137	    return url ?? fullURL;
138	  }
