28	/// Runs the Flutter tool with support for the specified list of [commands].
29	Future<int> run(
30	  List<String> args,
31	  List<FlutterCommand> commands, {
32	  bool muteCommandLogging = false,
33	  bool verbose = false,
34	  bool verboseHelp = false,
35	  bool reportCrashes,
36	  String flutterVersion,
37	  Map<Type, Generator> overrides,
38	}) {
39	  reportCrashes ??= !isRunningOnBot;
40	
41	  if (muteCommandLogging) {
42	    // Remove the verbose option; for help and doctor, users don't need to see
43	    // verbose logs.
44	    args = List<String>.from(args);
45	    args.removeWhere((String option) => option == '-v' || option == '--verbose');
46	  }
47	
48	  final FlutterCommandRunner runner = FlutterCommandRunner(verboseHelp: verboseHelp);
49	  commands.forEach(runner.addCommand);
50	
51	  return runInContext<int>(() async {
52	    // Initialize the system locale.
53	    final String systemLocale = await intl_standalone.findSystemLocale();
54	    intl.Intl.defaultLocale = intl.Intl.verifiedLocale(
55	      systemLocale, intl.NumberFormat.localeExists,
56	      onFailure: (String _) => 'en_US',
57	    );
58	
59	    String getVersion() => flutterVersion ?? FlutterVersion.instance.getVersionString(redactUnknownBranches: true);
60	    Object firstError;
61	    StackTrace firstStackTrace;
62	    return await runZoned<Future<int>>(() async {
63	      try {
64	        await runner.run(args);
65	        return await _exit(0);
66	      } catch (error, stackTrace) {
67	        firstError = error;
68	        firstStackTrace = stackTrace;
69	        return await _handleToolError(
70	            error, stackTrace, verbose, args, reportCrashes, getVersion);
71	      }
72	    }, onError: (Object error, StackTrace stackTrace) async {
73	      // If sending a crash report throws an error into the zone, we don't want
74	      // to re-try sending the crash report with *that* error. Rather, we want
75	      // to send the original error that triggered the crash report.
76	      final Object e = firstError ?? error;
77	      final StackTrace s = firstStackTrace ?? stackTrace;
78	      await _handleToolError(e, s, verbose, args, reportCrashes, getVersion);
79	    });
80	  }, overrides: overrides);
81	}
