83	Future<int> _handleToolError(
84	  dynamic error,
85	  StackTrace stackTrace,
86	  bool verbose,
87	  List<String> args,
88	  bool reportCrashes,
89	  String getFlutterVersion(),
90	) async {
91	  if (error is UsageException) {
92	    printError('${error.message}\n');
93	    printError("Run 'flutter -h' (or 'flutter <command> -h') for available flutter commands and options.");
94	    // Argument error exit code.
95	    return _exit(64);
96	  } else if (error is ToolExit) {
97	    if (error.message != null) {
98	      printError(error.message);
99	    }
100	    if (verbose) {
101	      printError('\n$stackTrace\n');
102	    }
103	    return _exit(error.exitCode ?? 1);
104	  } else if (error is ProcessExit) {
105	    // We've caught an exit code.
106	    if (error.immediate) {
107	      exit(error.exitCode);
108	      return error.exitCode;
109	    } else {
